namespace sv_e1533c387e25407f984d4e0766a55787.Models;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);

public record NotificationPrefs(
    bool EmailNotifications,
    bool PushNotifications,
    bool WeeklyDigest,
    List<string> MutedChannels);

public record SecuritySettings(
    bool TwoFactorEnabled,
    DateTime? LastPasswordChange,
    List<ActiveSession> Sessions);

public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);

public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

using sv_e1533c387e25407f984d4e0766a55787.Models;

namespace sv_e1533c387e25407f984d4e0766a55787.Services;

public class MockSettingsService : ISettingsService
{
    private UserProfile _profile = new(
        "John Doe",
        "john.doe@example.com",
        "https://via.placeholder.com/100",
        "Full-stack developer passionate about clean code and great UX.");

    private NotificationPrefs _notificationPrefs = new(
        EmailNotifications: true,
        PushNotifications: false,
        WeeklyDigest: true,
        MutedChannels: ["marketing"]);

    private SecuritySettings _securitySettings = new(
        TwoFactorEnabled: false,
        LastPasswordChange: DateTime.Now.AddDays(-45),
        Sessions:
        [
            new("sess-1", "Chrome on Windows", "New York, US", DateTime.Now.AddMinutes(-5)),
            new("sess-2", "Firefox on macOS", "London, UK", DateTime.Now.AddHours(-2)),
            new("sess-3", "Mobile Safari", "Tokyo, JP", DateTime.Now.AddDays(-1)),
        ]);

    private AppearanceSettings _appearance = new("Light", "Medium", "English", false);

    public Task<UserProfile> GetProfileAsync() =>
        Task.FromResult(_profile);

    public Task SaveProfileAsync(UserProfile profile)
    {
        _profile = profile;
        return Task.CompletedTask;
    }

    public Task<NotificationPrefs> GetNotificationPrefsAsync() =>
        Task.FromResult(_notificationPrefs);

    public Task SaveNotificationPrefsAsync(NotificationPrefs prefs)
    {
        _notificationPrefs = prefs;
        return Task.CompletedTask;
    }

    public Task<SecuritySettings> GetSecuritySettingsAsync() =>
        Task.FromResult(_securitySettings);

    public Task ChangePasswordAsync(string currentPassword, string newPassword)
    {
        _securitySettings = _securitySettings with { LastPasswordChange = DateTime.Now };
        return Task.CompletedTask;
    }

    public Task RevokeSessionAsync(string sessionId)
    {
        _securitySettings = _securitySettings with
        {
            Sessions = _securitySettings.Sessions
                .Where(s => s.Id != sessionId)
                .ToList()
        };
        return Task.CompletedTask;
    }

    public Task<AppearanceSettings> GetAppearanceAsync() =>
        Task.FromResult(_appearance);

    public Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        _appearance = settings;
        return Task.CompletedTask;
    }
}

@using sv_e1533c387e25407f984d4e0766a55787.Models

@if (Session is not null)
{
    <div class="modal-backdrop fade show"></div>
    <div class="modal d-block fade show" tabindex="-1">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="OnCancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke this session? The user will be signed out on that device.</p>
                    <ul class="list-unstyled mb-0">
                        <li><strong>Device:</strong> @Session.Device</li>
                        <li><strong>Location:</strong> @Session.Location</li>
                        <li><strong>Last active:</strong> @Session.LastActive.ToString("g")</li>
                    </ul>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="OnCancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="OnConfirm">Revoke</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public ActiveSession? Session { get; set; }
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }
}

@using sv_e1533c387e25407f984d4e0766a55787.Models

<div class="card">
    <div class="card-header">Live Preview</div>
    <div class="card-body @ThemeClasses" style="@ThemeBorder transition: all 0.2s ease;">
        <h6 style="@FontStyle">Sample Heading</h6>
        <p style="@FontStyle" class="@(Settings?.CompactMode == true ? "mb-1" : "mb-3")">
            This is a preview of how your content will look with the selected appearance settings.
            Language: <strong>@(Settings?.Language ?? "English")</strong>.
        </p>
        <div class="d-flex align-items-center gap-2">
            <button class="btn @ButtonClass @(Settings?.CompactMode == true ? "btn-sm" : "")">
                Sample Button
            </button>
            <span class="badge bg-secondary">Badge</span>
            <span class="badge @(IsDark ? "bg-light text-dark" : "bg-dark")">Label</span>
        </div>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }

    private bool IsDark => Settings?.Theme == "Dark";

    private string ThemeClasses => IsDark ? "bg-dark text-light" : "bg-light text-dark";

    private string ThemeBorder => IsDark
        ? "border: 1px solid #495057;"
        : "border: 1px solid #dee2e6;";

    private string FontStyle => Settings?.FontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.25rem;",
        _ => "font-size: 1rem;"
    };

    private string ButtonClass => IsDark ? "btn-light" : "btn-primary";
}

