{"path": "/tmp/sv-e1533c387e25407f984d4e0766a55787/Components/Pages/Settings/ChangePasswordPanel.razor", "file_text": "<div class="card mb-4">
    <div class="card-header d-flex justify-content-between align-items-center"
         role="button" @onclick="() => _expanded = !_expanded">
        <span>🔑 Change Password</span>
        <span>@(_expanded ? "▲" : "▼")</span>
    </div>
    @if (_expanded)
    {
        <div class="card-body">
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert @(_isError ? "alert-danger" : "alert-success") py-2">@_message</div>
            }
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="_currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="_newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="_confirmPassword" />
            </div>
            <button class="btn btn-warning" @onclick="SubmitAsync" disabled="@_submitting">
                @(_submitting ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _submitting;
    private string? _message;
    private bool _isError;

    private async Task SubmitAsync()
    {
        _message = null;

        if (string.IsNullOrWhiteSpace(_currentPassword)
            || string.IsNullOrWhiteSpace(_newPassword)
            || string.IsNullOrWhiteSpace(_confirmPassword))
        {
            _message = "All fields are required.";
            _isError = true;
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _message = "New passwords do not match.";
            _isError = true;
            return;
        }

        if (_newPassword.Length < 8)
        {
            _message = "Password must be at least 8 characters.";
            _isError = true;
            return;
        }

        _submitting = true;
        await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
        _submitting = false;
        _message = "Password updated successfully!";
        _isError = false;
        _currentPassword = _newPassword = _confirmPassword = "";
    }
}
"}

{"path": "/tmp/sv-e1533c387e25407f984d4e0766a55787/Components/Pages/Settings/AppearancePreview.razor", "file_text": "@using sv_e1533c387e25407f984d4e0766a55787.Models

<div class="card">
    <div class="card-header">Live Preview</div>
    <div class="card-body @ThemeClasses" style="@ThemeBorder transition: all 0.2s ease;">
        <h6 style="@FontStyle">Sample Heading</h6>
        <p style="@FontStyle" class="@(Settings?.CompactMode == true ? "mb-1" : "mb-3")">
            This is a preview of how your content will look with the selected appearance settings.
            Language: <strong>@(Settings?.Language ?? "English")</strong>.
        </p>
        <div class="d-flex align-items-center gap-2">
            <button class="btn @ButtonClass @(Settings?.CompactMode == true ? "btn-sm" : "")">
                Sample Button
            </button>
            <span class="badge bg-secondary">Badge</span>
            <span class="badge @(IsDark ? "bg-light text-dark" : "bg-dark")">Label</span>
        </div>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }

    private bool IsDark => Settings?.Theme == "Dark";

    private string ThemeClasses => IsDark ? "bg-dark text-light" : "bg-light text-dark";

    private string ThemeBorder => IsDark
        ? "border: 1px solid #495057;"
        : "border: 1px solid #dee2e6;";

    private string FontStyle => Settings?.FontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.25rem;",
        _ => "font-size: 1rem;"
    };

    private string ButtonClass => IsDark ? "btn-light" : "btn-primary";
}
"}

