<h4 class="mb-3">Security Settings</h4>

<ChangePasswordPanel OnChangePassword="OnChangePassword" />

<div class="card mb-4">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center">
            <div>
                <h6 class="mb-1">Two-Factor Authentication</h6>
                <span class="badge @(Settings.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <div class="form-check form-switch mb-0">
                <input class="form-check-input" type="checkbox"
                       checked="@Settings.TwoFactorEnabled"
                       @onchange="e => OnToggle2FA.InvokeAsync((bool)e.Value!)" />
            </div>
        </div>
        @if (Settings.LastPasswordChange.HasValue)
        {
            <small class="text-muted d-block mt-2">
                Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </small>
        }
    </div>
</div>

<h5 class="mb-3">Active Sessions</h5>
<div class="table-responsive">
    <table class="table table-hover align-middle">
        <thead class="table-light">
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th class="text-end"></th>
            </tr>
        </thead>
        <tbody>
            @for (var i = 0; i < Settings.Sessions.Count; i++)
            {
                var session = Settings.Sessions[i];
                var isCurrent = i == 0;
                <tr>
                    <td>@session.Device</td>
                    <td>@session.Location</td>
                    <td>@session.LastActive.ToString("g")</td>
                    <td class="text-end">
                        @if (isCurrent)
                        {
                            <span class="badge bg-info">Current</span>
                        }
                        else
                        {
                            <button class="btn btn-sm btn-outline-danger"
                                    @onclick="() => _sessionToRevoke = session">
                                Revoke
                            </button>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>

<RevokeSessionDialog Session="_sessionToRevoke"
                      OnConfirm="ConfirmRevokeAsync"
                      OnCancel="() => _sessionToRevoke = null" />

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<bool> OnToggle2FA { get; set; }

    private ActiveSession? _sessionToRevoke;

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }
}

