@using sv_e1533c387e25407f984d4e0766a55787.Models

@if (Prefs is null)
{
    <p>Loading notifications...</p>
    return;
}

<h4 class="mb-3">Notification Preferences</h4>

<div class="mb-4">
    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
        <label class="form-check-label" for="emailNotif">Email Notifications</label>
    </div>
    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
        <label class="form-check-label" for="pushNotif">Push Notifications</label>
    </div>
    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
        <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
    </div>
</div>

<h5>Muted Channels</h5>
<p class="text-muted small">Select channels you want to mute.</p>
<div class="mb-4">
    @foreach (var channel in _allChannels)
    {
        var isMuted = _mutedChannels.Contains(channel);
        <div class="form-check mb-1">
            <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                   checked="@isMuted"
                   @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
            <label class="form-check-label text-capitalize" for="@($"ch-{channel}")">@channel</label>
        </div>
    }
</div>

<button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
    @(_saving ? "Saving..." : "Save Preferences")
</button>

@if (!string.IsNullOrEmpty(_successMessage))
{
    <span class="text-success ms-2">@_successMessage</span>
}

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private static readonly string[] _allChannels =
        ["general", "announcements", "marketing", "engineering", "support"];

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _saving;
    private string? _successMessage;
    private NotificationPrefs? _lastPrefs;

    protected override void OnParametersSet()
    {
        if (Prefs != _lastPrefs)
        {
            _lastPrefs = Prefs;
            ResetFields();
        }
    }

    private void ResetFields()
    {
        if (Prefs is null) return;
        _emailNotifications = Prefs.EmailNotifications;
        _pushNotifications = Prefs.PushNotifications;
        _weeklyDigest = Prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(Prefs.MutedChannels);
        _successMessage = null;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted) _mutedChannels.Add(channel);
        else _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var updated = new NotificationPrefs(
            _emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _successMessage = "Preferences saved!";
    }
}

