@using sv_e1533c387e25407f984d4e0766a55787.Models

@if (Profile is null)
{
    <p>Loading profile...</p>
    return;
}

<h4 class="mb-3">Profile Settings</h4>

@if (!string.IsNullOrEmpty(_successMessage))
{
    <div class="alert alert-success alert-dismissible fade show py-2" role="alert">
        @_successMessage
        <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
    </div>
}

<div class="row">
    <div class="col-md-8">
        <div class="mb-3">
            <label class="form-label fw-semibold">Display Name</label>
            <input class="form-control" @bind="_displayName" />
        </div>
        <div class="mb-3">
            <label class="form-label fw-semibold">Email</label>
            <input type="email" class="form-control" @bind="_email" />
        </div>
        <div class="mb-3">
            <label class="form-label fw-semibold">Bio</label>
            <textarea class="form-control" rows="4" @bind="_bio"></textarea>
        </div>
    </div>
    <div class="col-md-4 text-center">
        <div class="mb-3">
            <img src="@_avatarUrl" alt="Avatar" class="rounded-circle border"
                 style="width: 100px; height: 100px; object-fit: cover;" />
        </div>
        <div class="mb-3">
            <label class="form-label fw-semibold">Avatar URL</label>
            <input class="form-control form-control-sm" @bind="_avatarUrl" placeholder="https://..." />
        </div>
    </div>
</div>

<div class="d-flex gap-2 mt-2">
    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
        @(_saving ? "Saving..." : "Save Changes")
    </button>
    <button class="btn btn-outline-secondary" @onclick="Discard">
        Discard Changes
    </button>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";
    private bool _saving;
    private string? _successMessage;
    private UserProfile? _lastProfile;

    protected override void OnParametersSet()
    {
        if (Profile != _lastProfile)
        {
            _lastProfile = Profile;
            ResetFields();
        }
    }

    private void ResetFields()
    {
        if (Profile is null) return;
        _displayName = Profile.DisplayName;
        _email = Profile.Email;
        _bio = Profile.Bio;
        _avatarUrl = Profile.AvatarUrl;
        _successMessage = null;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _successMessage = "Profile saved successfully!";
    }

    private void Discard() => ResetFields();
}

