@using sv_e1533c387e25407f984d4e0766a55787.Models

@if (Settings is null)
{
    <p>Loading security settings...</p>
    return;
}

<h4 class="mb-3">Security Settings</h4>

<ChangePasswordPanel OnChangePassword="OnChangePassword" />

<div class="card mb-4">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center">
            <div>
                <h6 class="mb-1">Two-Factor Authentication</h6>
                <span class="badge @(Settings.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <div class="form-check form-switch mb-0">
                <input class="form-check-input" type="checkbox"
                       checked="@Settings.TwoFactorEnabled"
                       @onchange="e => OnToggle2FA.InvokeAsync((bool)e.Value!)" />
            </div>
        </div>
        @if (Settings.LastPasswordChange.HasValue)
        {
            <small class="text-muted d-block mt-2">
                Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </small>
        }
    </div>
</div>

<h5 class="mb-3">Active Sessions</h5>
<div class="table-responsive">
    <table class="table table-hover align-middle">
        <thead class="table-light">
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th class="text-end"></th>
            </tr>
        </thead>
        <tbody>
            @for (var i = 0; i < Settings.Sessions.Count; i++)
            {
                var session = Settings.Sessions[i];
                var isCurrent = i == 0;
                <tr>
                    <td>@session.Device</td>
                    <td>@session.Location</td>
                    <td>@session.LastActive.ToString("g")</td>
                    <td class="text-end">
                        @if (isCurrent)
                        {
                            <span class="badge bg-info">Current</span>
                        }
                        else
                        {
                            <button class="btn btn-sm btn-outline-danger"
                                    @onclick="() => _sessionToRevoke = session">
                                Revoke
                            </button>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>

<RevokeSessionDialog Session="_sessionToRevoke"
                      OnConfirm="ConfirmRevokeAsync"
                      OnCancel="() => _sessionToRevoke = null" />

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<bool> OnToggle2FA { get; set; }

    private ActiveSession? _sessionToRevoke;

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }
}

@using sv_e1533c387e25407f984d4e0766a55787.Models

@if (Settings is null)
{
    <p>Loading appearance settings...</p>
    return;
}

<h4 class="mb-3">Appearance Settings</h4>

<div class="row">
    <div class="col-md-6">
        <div class="mb-4">
            <h6 class="fw-semibold">Theme</h6>
            @foreach (var theme in _themes)
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="theme"
                           id="@($"theme-{theme}")"
                           checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6 class="fw-semibold">Font Size</h6>
            @foreach (var size in _fontSizes)
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="fontSize"
                           id="@($"size-{size}")"
                           checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    <label class="form-check-label" for="@($"size-{size}")">@size</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6 class="fw-semibold">Language</h6>
            <select class="form-select" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>
        </div>

        <div class="d-flex align-items-center gap-2">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving..." : "Save")
            </button>
            @if (!string.IsNullOrEmpty(_successMessage))
            {
                <span class="text-success">@_successMessage</span>
            }
        </div>
    </div>

    <div class="col-md-6">
        <AppearancePreview Settings="@CurrentPreview" />
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _saving;
    private string? _successMessage;
    private AppearanceSettings? _lastSettings;

    private AppearanceSettings CurrentPreview => new(_theme, _fontSize, _language, _compactMode);

    protected override void OnParametersSet()
    {
        if (Settings != _lastSettings)
        {
            _lastSettings = Settings;
            if (Settings is null) return;
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
            _successMessage = null;
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        await OnSave.InvokeAsync(CurrentPreview);
        _saving = false;
        _successMessage = "Appearance saved!";
    }
}

